import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long low = 1, high = 1000000000000L;
        while (low < high) {
            long mid = (low + high) / 2;
            if (count(mid) >= N) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        System.out.println(low);
    }
    static long count(long x) {
        long res = 0;
        for (long a = 1; a <= x; a++) {
            long b = a + 1;
            long val = a * a + b * b;
            if (val > x) break;
            res += x / val;
        }
        return res;
    }
}
