            long mid = (low + high) / 2;
            if (count(mid) >= N) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        System.out.println(low);
    }
    static long count(long x) {
        long res = 0;
        for (long k = 1; k <= x / 2; k++) {
            res += x / (2 * k) - x / (2 * k + 1);
        }
        return res;
    }
