public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long low = 1, high = 2_000_000_000_000_000_000L;
        while (low < high) {
            long mid = (low + high) / 2;
            if (count(mid) >= N) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        System.out.println(low);
    }
    static long count(long x) {
        long res = 0;
        for (long a = 1; a * a <= x; a++) {
            long b = x / a;
            if (b > a) {
                res += b - a;
            }
        }
        return res;
    }
}
